import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());

    // Connection pool managed by container
    private DataSource getDataSource() throws Exception {
        javax.naming.InitialContext ctx = new javax.naming.InitialContext();
        return (DataSource) ctx.lookup("java:comp/env/jdbc/ReportsDB");
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String department = req.getParameter("dept");

        // Input validation - check for obviously malicious patterns
        if (reportType == null || reportType.length() > 50) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Sanitize: remove comments and semicolons
        reportType = reportType.replaceAll("--", "").replaceAll(";", "");
        department = (department != null) ? department.replaceAll("--", "").replaceAll(";", "") : "ALL";

        // Build query based on report parameters
        String query = buildReportQuery(reportType, dateRange, department);

        log.info("Executing report query for type=" + reportType + " dept=" + department);

        try (Connection conn = getDataSource().getConnection();
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.println("{\'results\': [");

            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            while (rs.next()) {
                if (!first) out.println(",");
                out.print("{");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(",");
                    out.print("\"" + meta.getColumnName(i) + "\":");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.println("}");
                first = false;
            }
            out.println("]}");

        } catch (Exception e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildReportQuery(String type, String range, String dept) {
        StringBuilder sb = new StringBuilder();
        sb.append("SELECT * FROM reports WHERE report_type = '");
        sb.append(type);
        sb.append("'");

        if (range != null && !range.isEmpty()) {
            sb.append(" AND created_date >= DATE_SUB(NOW(), INTERVAL ");
            sb.append(range);
            sb.append(")");
        }

        if (!"ALL".equals(dept)) {
            sb.append(" AND department = '");
            sb.append(dept);
            sb.append("'");
        }

        sb.append(" ORDER BY created_date DESC LIMIT 1000");
        return sb.toString();
    }
}
